contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newImpl, bool asOwner) public payable {
        require(newImpl != address(0));
        // set up: initialize c so that this contract (msg.sender) is the owner
        c.initialize();
        // decide who calls: owner = this contract, non-owner = random unpowdered fresh address is not callable,
        // so use this contract as owner and a second fresh contract as non-owner via create? Not allowed.
        // Instead: owner case -> call directly; non-owner case -> use renounce path is impossible for non-owner.
        // We test: as owner, update succeeds and sets state; as non-owner, reverts (owner stays unchanged).
        address before = c.roundImplementation();
        bool reverted;
        if (asOwner) {
            try c.updateRoundImplementation(payable(newImpl)) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted && c.roundImplementation() == newImpl);
        } else {
            // a non-owner: any address without code and not msg.sender cannot be msg.sender,
            // so simulate by renouncing then retrying with the owner address
            c.renounceOwnership();
            address ownerBefore = c.owner();
            try c.updateRoundImplementation(payable(newImpl)) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted && c.owner() == ownerBefore && c.roundImplementation() == before);
        }
    }
    receive() external payable {}
}

